using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BRTreads {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B2/";
 class Tri{public int sub;public int[] ids;public Vector3[] p;public Vector3 center;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(var suffix in new[]{"Base","MS","Normal"}){string p=E+"Textures/BR_Tread_"+suffix+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=suffix=="Normal"?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=suffix=="Base";ti.mipmapEnabled=true;ti.anisoLevel=8;ti.wrapMode=TextureWrapMode.Clamp;ti.SaveAndReimport();}
 string matPath=E+"Materials/BR_Tread.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BR_Tread"};AssetDatabase.CreateAsset(mat,matPath);}mat.SetColor("_BaseColor",Color.white);mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/BR_Tread_Base.png"));mat.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/BR_Tread_MS.png"));mat.SetFloat("_Smoothness",1);mat.EnableKeyword("_METALLICSPECGLOSSMAP");EditorUtility.SetDirty(mat);
 int surfaces=0,renderers=0;var all=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).ToArray();var cache=new Dictionary<Mesh,Mesh>();foreach(var mf in all){var mr=mf.GetComponent<MeshRenderer>();if(!mr||!mr.enabled||!mf.sharedMesh)continue;string path=AssetDatabase.GetAssetPath(mf.sharedMesh);if(!(path.Contains("OperationsDeck")||path.Contains("_UpperWalk")||path.Contains("BM_VerticalStairs"))||path.Contains("Collision")||mr.sharedMaterials.Any(m=>m.name=="BR_Tread"))continue;var src=mf.sharedMesh;var mats=mr.sharedMaterials;Mesh result;if(!cache.TryGetValue(src,out result)){
 var sourceV=src.vertices;var normals=src.normals;var sourceUv=src.uv;var groups=new List<List<Tri>>();var original=new List<int>[src.subMeshCount];for(int sub=0;sub<src.subMeshCount;sub++){original[sub]=src.GetTriangles(sub).ToList();if(!mats[sub].name.Contains("Steel"))continue;var ts=src.GetTriangles(sub);for(int i=0;i<ts.Length;i+=3){var ids=new[]{ts[i],ts[i+1],ts[i+2]};var p=ids.Select(v=>mf.transform.TransformPoint(sourceV[v])).ToArray();var cross=Vector3.Cross(p[1]-p[0],p[2]-p[0]);float height=p[0].y+34;if(cross.normalized.y<.97f||cross.magnitude<.024f||height<.2f)continue;var c=(p[0]+p[1]+p[2])/3;var g=groups.FirstOrDefault(q=>Mathf.Abs(q[0].center.y-c.y)<.008f&&Vector3.Distance(q[0].center,c)<1.6f);if(g==null){g=new List<Tri>();groups.Add(g);}g.Add(new Tri{sub=sub,ids=ids,p=p,center=c});}}
 var vlist=sourceV.ToList();var nlist=normals.ToList();var ulist=sourceUv.ToList();var top=new List<int>();var selected=new HashSet<Tri>();foreach(var group in groups){var points=group.SelectMany(t=>t.p).ToArray();var center=points.Aggregate(Vector3.zero,(a,b)=>a+b)/points.Length;float xx=0,xz=0,zz=0;foreach(var p in points){var d=p-center;xx+=d.x*d.x;xz+=d.x*d.z;zz+=d.z*d.z;}float angle=.5f*Mathf.Atan2(2*xz,xx-zz);var right=new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle));var forward=new Vector3(-right.z,0,right.x);var u=points.Select(p=>Vector3.Dot(p-center,right)).ToArray();var v=points.Select(p=>Vector3.Dot(p-center,forward)).ToArray();float w=u.Max()-u.Min(),d2=v.Max()-v.Min();if(w<1.1f||w>2.0f||d2<.13f||d2>1.15f)continue;foreach(var t in group){selected.Add(t);for(int j=0;j<3;j++){int id=t.ids[j];top.Add(vlist.Count);vlist.Add(sourceV[id]);nlist.Add(normals[id]);ulist.Add(new Vector2((Vector3.Dot(t.p[j]-center,right)-u.Min())/w,(Vector3.Dot(t.p[j]-center,forward)-v.Min())/d2));}}surfaces++;}
 if(top.Count==0)continue;for(int sub=0;sub<original.Length;sub++){var remove=selected.Where(t=>t.sub==sub).Select(t=>string.Join(",",t.ids)).ToHashSet();var keep=new List<int>();for(int i=0;i<original[sub].Count;i+=3)if(!remove.Contains(original[sub][i]+","+original[sub][i+1]+","+original[sub][i+2]))keep.AddRange(original[sub].GetRange(i,3));original[sub]=keep;}
 result=new Mesh{name=src.name+"_WornTreads",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};result.SetVertices(vlist);result.SetNormals(nlist);result.SetUVs(0,ulist);result.subMeshCount=original.Length+1;for(int i=0;i<original.Length;i++)result.SetTriangles(original[i],i);result.SetTriangles(top,original.Length);result.RecalculateBounds();result.RecalculateTangents();string outPath=E+"BR_Meshes/BR_Treads_"+AssetDatabase.AssetPathToGUID(path)+".asset";AssetDatabase.CreateAsset(result,outPath);cache[src]=result;}
 mf.sharedMesh=result;mr.sharedMaterials=mats.Concat(new[]{mat}).ToArray();if(PrefabUtility.IsPartOfPrefabInstance(mf)){PrefabUtility.RecordPrefabInstancePropertyModifications(mf);PrefabUtility.RecordPrefabInstancePropertyModifications(mr);}renderers++;}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var report=new{treadSurfaces=surfaces,renderers,collisionUnchanged=true};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-10_B2_SurfaceRefinement/treads.json")),JsonConvert.SerializeObject(report,Formatting.Indented));return report;}
}
